const testCases = [
  {
    name: 'API Discovery - Returns Catalog',
    method: 'GET',
    url: 'https://mmurawala.app.n8n.cloud/webhook/api-discovery',
    expected: { has_field: 'apis' }
  },
  {
    name: 'Gateway - Valid Request Structure',
    method: 'POST',
    url: 'https://mmurawala.app.n8n.cloud/webhook/api-gateway',
    headers: { 'X-API-KEY': 'test-key' },
    body: { client: 'test-runner', api: 'google_ads', action: 'campaigns', params: {} },
    expected: { has_field: 'request_id' }
  },
  {
    name: 'Gateway - Missing Required Fields',
    method: 'POST',
    url: 'https://mmurawala.app.n8n.cloud/webhook/api-gateway',
    headers: { 'X-API-KEY': 'test-key' },
    body: { client: 'test-runner' },
    expected: { has_field: 'validation_errors' }
  },
  {
    name: 'Gateway - Unknown API',
    method: 'POST',
    url: 'https://mmurawala.app.n8n.cloud/webhook/api-gateway',
    headers: { 'X-API-KEY': 'test-key' },
    body: { client: 'test-runner', api: 'nonexistent_api', action: 'test', params: {} },
    expected: { has_field: 'available_apis' }
  },
  {
    name: 'Health Check - Returns Report',
    method: 'GET',
    url: 'https://mmurawala.app.n8n.cloud/webhook/health-check',
    expected: { has_field: 'health_report' }
  }
];

return testCases.map(tc => ({ json: tc }));

const testCase = $('Define Test Cases').first().json;
const result = $input.first().json;

const passed = testCase.expected.has_field ? 
  result[testCase.expected.has_field] !== undefined : true;

return [{
  json: {
    test_name: testCase.name,
    passed: passed,
    expected: testCase.expected,
    actual_keys: Object.keys(result),
    response_snippet: JSON.stringify(result).substring(0, 200)
  }
}];

// Aggregate all test results into a final report
const allResults = $input.all();

const report = {
  test_run_id: $execution.id,
  executed_at: new Date().toISOString(),
  total_tests: allResults.length,
  passed: 0,
  failed: 0,
  results: []
};

for (const item of allResults) {
  const r = item.json;
  report.results.push(r);
  if (r.passed) {
    report.passed++;
  } else {
    report.failed++;
  }
}

report.success_rate = report.total_tests > 0
  ? ((report.passed / report.total_tests) * 100).toFixed(1) + '%'
  : '0%';
report.overall_status = report.failed === 0 ? 'PASS' : 'FAIL';

return [{ json: report }];
